294	/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
295	export function getAwakeningLevel(grade: string, duplicateCount: number): number {
296	  if (grade === 'R') {
297	    if (duplicateCount >= 100) return 5;
298	    if (duplicateCount >= 75)  return 4;
299	    if (duplicateCount >= 50)  return 3;
300	    if (duplicateCount >= 25)  return 2;
301	    if (duplicateCount >= 10)  return 1;
302	  } else if (grade === 'SR') {
303	    if (duplicateCount >= 40) return 5;
304	    if (duplicateCount >= 25) return 4;
305	    if (duplicateCount >= 15) return 3;
306	    if (duplicateCount >= 7)  return 2;
307	    if (duplicateCount >= 3)  return 1;
308	  } else if (grade === 'UR') {
309	    if (duplicateCount >= 10) return 5;
310	    if (duplicateCount >= 6)  return 4;
311	    if (duplicateCount >= 4)  return 3;
312	    if (duplicateCount >= 2)  return 2;
313	    if (duplicateCount >= 1)  return 1;
314	  }
315	  return 0;
316	}
317	
318	const DUPES_KEY     = 'duplicateCounts';
319	const DUPES_SIG_KEY = 'duplicateCountsSig';
320	const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';
321	
322	/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
323	function _signDupes(map: Record<string, number>): string {
324	  const str = Object.entries(map)
325	    .sort(([a], [b]) => a.localeCompare(b))
326	    .map(([k, v]) => `${k}:${v}`)
327	    .join(',') + _DUPES_SALT;
328	  let h = 5381;
329	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
330	  return h.toString(36);
331	}
332	
333	function _saveDupes(map: Record<string, number>): void {
334	  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
335	  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
336	}
337	
338	/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
339	export function getDuplicateCount(id: string): number {
340	  try {
341	    const raw = localStorage.getItem(DUPES_KEY);
342	    const sig = localStorage.getItem(DUPES_SIG_KEY);
343	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
344	
345	    if (sig === null) {
346	      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
347	      _saveDupes(map);
348	      return map[id] ?? 0;
349	    }
350	
351	    // 서명 불일치 → 변조로 판단, 전체 초기화
352	    if (sig !== _signDupes(map)) {
353	      _saveDupes({});
354	      return 0;
355	    }
356	
357	    return map[id] ?? 0;
358	  } catch {
359	    return 0;
360	  }
361	}
362	
363	/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
364	export function setDuplicateCount(id: string, count: number): void {
365	  try {
366	    const raw = localStorage.getItem(DUPES_KEY);
367	    const sig = localStorage.getItem(DUPES_SIG_KEY);
368	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
369	
370	    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
371	    if (sig !== null && sig !== _signDupes(map)) {
372	      _saveDupes({ [id]: count });
373	      return;
374	    }
375	
376	    map[id] = count;
377	    _saveDupes(map);
378	  } catch { /* ignore */ }
379	}
380	
381	const OWNED_KEY = 'ownedCharacters';
382	const OWNED_SIG_KEY = 'ownedCharactersSig';
383	const SELECTED_KEY = 'selectedCharacter';
384	const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';
385	
386	/** djb2 해시 → base36 문자열 (무결성 서명용) */
387	function _sign(list: string[]): string {
388	  const str = [...list].sort().join(',') + _SIG_SALT;
389	  let h = 5381;
390	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
391	  return h.toString(36);
392	}
393	
394	/** 보유 목록과 서명을 함께 저장 (내부 전용) */
395	function _saveOwned(list: string[]): void {
396	  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
397	  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
398	}
399	
400	/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
401	export function getOwnedCharacters(): string[] {
402	  try {
403	    const raw = localStorage.getItem(OWNED_KEY);
404	    const sig = localStorage.getItem(OWNED_SIG_KEY);
405	    const list: string[] = raw ? JSON.parse(raw) : [];
406	    if (!list.includes('chibi')) list.unshift('chibi');
407	
408	    if (sig === null) {
409	      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
410	      _saveOwned(list);
411	      return list;
412	    }
413	
414	    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
415	    if (sig !== _sign(list)) {
416	      _saveOwned(['chibi']);
417	      return ['chibi'];
418	    }
419	
420	    return list;
421	  } catch {
422	    return ['chibi'];
423	  }
424	}
425	
426	/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
427	export function setOwnedCharacters(list: string[]): void {
428	  if (!list.includes('chibi')) list.unshift('chibi');
429	  _saveOwned(list);
430	}
431	
432	/** 캐릭터를 보유 목록에 추가 (뽑기 완료 후 호출) */
433	export function addOwnedCharacter(id: string): void {
434	  const owned = getOwnedCharacters();
435	  if (!owned.includes(id)) {
436	    owned.push(id);
437	    _saveOwned(owned);
438	  }
439	}
440	
441	/** 선택된 캐릭터 ID 반환. 없으면 'chibi'. */
442	export function getSelectedCharacter(): string {
443	  return localStorage.getItem(SELECTED_KEY) ?? 'chibi';
444	}
445	
446	/** 선택된 캐릭터 저장 */
447	export function setSelectedCharacter(id: string): void {
448	  localStorage.setItem(SELECTED_KEY, id);
449	}
450	
451	/** 소유 목록과 교차 검증하여 안전한 캐릭터 ID 반환. 미보유면 'chibi'로 강제 초기화. */
452	export function getSafeSelectedCharacter(): string {
453	  const selected = getSelectedCharacter();
454	  const owned = getOwnedCharacters();
455	  if (owned.includes(selected)) return selected;
456	  // 변조 감지 → chibi로 강제 초기화
457	  setSelectedCharacter('chibi');
458	  return 'chibi';
459	}
460	
461	/** 캐릭터 정의 조회 */
462	export function getCharacterDef(id: string): CharacterDef {
463	  return CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
464	}
