1	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
2	
3	const corsHeaders = {
4	  'Access-Control-Allow-Origin': '*',
5	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
6	};
7	
8	// ── 배경화면 풀 정의 ─────────────────────────────────────────────────────
9	// 등급 없음. 10종 균등 확률.
10	// 뽑기당 드롭율 3.5% → 종당 실효 확률 0.35% (캐릭터 UR과 동일 수준)
11	const WP_DROP_CHANCE = 0.035; // 슬롯당 3.5% → 종당 실효 확률 약 1.17%
12	const WP_POOL = [
13	  { id: 'wp_hanok'     },
14	  { id: 'wp_lake'      },
15	  { id: 'wp_maehwa'    },
16	  { id: 'wp_gold_mine' },
17	  { id: 'wp_fantasy'   },
18	];
19	
20	function pullWallpaper(): { id: string } {
21	  return WP_POOL[Math.floor(Math.random() * WP_POOL.length)];
22	}
23	
24	// ── 뽑기 풀 정의 ────────────────────────────────────────────────────────
25	// R 80% (10종 균등 배분), SR 19.3% (7종 균등 배분), UR 0.7% (2종 균등 배분)
26	const SR_W  = 19.3 / 7;   // ≈ 2.757%
27	const POOL = [
28	  // ── R등급 ──
29	  { id: 'log',     grade: 'R',  weight: 8 },
30	  { id: 'swap',    grade: 'R',  weight: 8 },
31	  { id: 'sum',     grade: 'R',  weight: 8 },
32	  { id: 'fork',    grade: 'R',  weight: 8 },
33	  { id: 'seed',    grade: 'R',  weight: 8 },
34	  { id: 'session', grade: 'R',  weight: 8 },
35	  { id: 'branch',  grade: 'R',  weight: 8 },
36	  { id: 'hook',    grade: 'R',  weight: 8 },
37	  { id: 'socket',  grade: 'R',  weight: 8 },
38	  { id: 'index',   grade: 'R',  weight: 8 },
39	  // ── SR등급 ──
40	  { id: 'hacker',   grade: 'SR', weight: SR_W },
41	  { id: 'miner',    grade: 'SR', weight: SR_W },
42	  { id: 'maehwa',   grade: 'SR', weight: SR_W },
43	  { id: 'archieve', grade: 'SR', weight: SR_W },
44	  { id: 'glitch',   grade: 'SR', weight: SR_W },
45	  { id: 'noise',    grade: 'SR', weight: SR_W },
46	  { id: 'knight',   grade: 'SR', weight: SR_W },
47	  // ── UR등급 ──
48	  { id: 'sentinel', grade: 'UR', weight: 0.35 },
49	  { id: 'legacy',   grade: 'UR', weight: 0.35 },
50	];
51	
52	function pullOne(): { id: string; grade: string } {
53	  const total = POOL.reduce((s, c) => s + c.weight, 0);
54	  let r = Math.random() * total;
55	  for (const c of POOL) {
56	    r -= c.weight;
57	    if (r <= 0) return { id: c.id, grade: c.grade };
58	  }
59	  return { id: POOL[POOL.length - 1].id, grade: POOL[POOL.length - 1].grade };
60	}
61	
62	// ── 요청 처리 ───────────────────────────────────────────────────────────
63	Deno.serve(async (req: Request) => {
64	  if (req.method === 'OPTIONS') {
65	    return new Response('ok', { headers: corsHeaders });
66	  }
67	
68	  try {
69	    const { pullType } = await req.json(); // 'single' | 'multi'
70	
71	    if (pullType !== 'single' && pullType !== 'multi') {
72	      return new Response(
73	        JSON.stringify({ error: 'Invalid pullType' }),
74	        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
75	      );
76	    }
77	
78	    const cost = pullType === 'multi' ? 900 : 100;
79	    const count = pullType === 'multi' ? 10 : 1;
80	
81	    // 인증
82	    const authHeader = req.headers.get('Authorization');
83	    if (!authHeader) {
84	      return new Response(
85	        JSON.stringify({ error: 'Missing authorization header' }),
86	        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
87	      );
88	    }
89	
90	    const supabaseUser = createClient(
91	      Deno.env.get('SUPABASE_URL') ?? '',
92	      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
93	      { global: { headers: { Authorization: authHeader } } }
94	    );
95	
96	    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
97	    if (authError || !user) {
98	      return new Response(
99	        JSON.stringify({ error: 'Unauthorized' }),
100	        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
101	      );
102	    }
103	
104	    const supabaseAdmin = createClient(
105	      Deno.env.get('SUPABASE_URL') ?? '',
106	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
107	    );
108	
109	    // ── 1. SKOR 잔액 + 보유 캐릭터 + 보유 배경화면 병렬 조회 ────────
110	    const [{ data: skorData }, { data: owned }, { data: ownedWp }] = await Promise.all([
111	      supabaseAdmin.from('user_skor').select('balance').eq('user_id', user.id).single(),
112	      supabaseAdmin.from('user_characters').select('character_id').eq('user_id', user.id),
113	      supabaseAdmin.from('user_wallpapers').select('wallpaper_id').eq('user_id', user.id),
114	    ]);
115	
116	    const balance = skorData?.balance ?? 0;
117	    if (balance < cost) {
118	      return new Response(
119	        JSON.stringify({ error: 'Insufficient SKOR', balance }),
120	        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
121	      );
122	    }
123	
124	    // ── 2. 슬롯별 결정: 각 슬롯은 배경화면 또는 캐릭터 중 하나
125	    //       총합 = count, 추가 드롭 없음 ────────────────────────────────
126	    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
127	    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));
128	
129	    const characters: { id: string; grade: string; isNew: boolean }[] = [];
130	    const wallpapers: { id: string; isNew: boolean }[] = [];
131	
132	    for (let i = 0; i < count; i++) {
133	      if (Math.random() < WP_DROP_CHANCE) {
134	        // 이 슬롯은 배경화면
135	        const wp = pullWallpaper();
136	        wallpapers.push({ id: wp.id, isNew: !ownedWpSet.has(wp.id) });
137	        ownedWpSet.add(wp.id); // 같은 pull 내 중복 isNew 방지
138	      } else {
139	        // 이 슬롯은 캐릭터
140	        const char = pullOne();
141	        characters.push({ id: char.id, grade: char.grade, isNew: !ownedSet.has(char.id) });
142	        ownedSet.add(char.id); // 같은 pull 내 중복 isNew 방지
143	      }
144	    }
145	
146	    // ── 3. 신규 배경화면 등록 ────────────────────────────────────────────
147	    const newWps = wallpapers
148	      .filter(w => w.isNew)
149	      .map(w => ({ user_id: user.id, wallpaper_id: w.id }));
150	
151	    // ── 4. 신규 캐릭터 등록 + 중복 카운트 증가 + SKOR 차감 병렬 처리 ─────
152	    // 같은 캐릭터가 10연차에서 중복 등장할 수 있으므로 횟수 집계 후 처리
153	    const newChars = [...new Map(
