  private spawnRainbowPoop() {
    if (this.gameOver) return;

    const x = Phaser.Math.Between(50, this.scale.width - 50);
    const y = -50;
    const rainbowPoop = this.rainbowPoops.get() as RainbowPoop;
    if (!rainbowPoop) return;
