/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
export function getAwakeningLevel(grade: string, duplicateCount: number): number {
  if (grade === 'R') {
    if (duplicateCount >= 100) return 5;
    if (duplicateCount >= 75)  return 4;
    if (duplicateCount >= 50)  return 3;
    if (duplicateCount >= 25)  return 2;
    if (duplicateCount >= 10)  return 1;
  } else if (grade === 'SR') {
    if (duplicateCount >= 40) return 5;
    if (duplicateCount >= 25) return 4;
    if (duplicateCount >= 15) return 3;
    if (duplicateCount >= 7)  return 2;
    if (duplicateCount >= 3)  return 1;
  } else if (grade === 'UR') {
    if (duplicateCount >= 10) return 5;
    if (duplicateCount >= 6)  return 4;
    if (duplicateCount >= 4)  return 3;
    if (duplicateCount >= 2)  return 2;
    if (duplicateCount >= 1)  return 1;
  }
  return 0;
}

const DUPES_KEY     = 'duplicateCounts';
const DUPES_SIG_KEY = 'duplicateCountsSig';
const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';

/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
function _signDupes(map: Record<string, number>): string {
  const str = Object.entries(map)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}:${v}`)
    .join(',') + _DUPES_SALT;
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36);
}

function _saveDupes(map: Record<string, number>): void {
  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
}

/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
export function getDuplicateCount(id: string): number {
  try {
    const raw = localStorage.getItem(DUPES_KEY);
    const sig = localStorage.getItem(DUPES_SIG_KEY);
    const map: Record<string, number> = raw ? JSON.parse(raw) : {};

    if (sig === null) {
      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
      _saveDupes(map);
      return map[id] ?? 0;
    }

    // 서명 불일치 → 변조로 판단, 전체 초기화
    if (sig !== _signDupes(map)) {
      _saveDupes({});
      return 0;
    }

    return map[id] ?? 0;
  } catch {
    return 0;
  }
}

/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
export function setDuplicateCount(id: string, count: number): void {
  try {
    const raw = localStorage.getItem(DUPES_KEY);
    const sig = localStorage.getItem(DUPES_SIG_KEY);
    const map: Record<string, number> = raw ? JSON.parse(raw) : {};

    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
    if (sig !== null && sig !== _signDupes(map)) {
      _saveDupes({ [id]: count });
      return;
    }

    map[id] = count;
    _saveDupes(map);
  } catch { /* ignore */ }
}

const OWNED_KEY = 'ownedCharacters';
const OWNED_SIG_KEY = 'ownedCharactersSig';
const SELECTED_KEY = 'selectedCharacter';
const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';

/** djb2 해시 → base36 문자열 (무결성 서명용) */
function _sign(list: string[]): string {
  const str = [...list].sort().join(',') + _SIG_SALT;
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36);
}

/** 보유 목록과 서명을 함께 저장 (내부 전용) */
function _saveOwned(list: string[]): void {
  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
}

/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
export function getOwnedCharacters(): string[] {
  try {
    const raw = localStorage.getItem(OWNED_KEY);
    const sig = localStorage.getItem(OWNED_SIG_KEY);
    const list: string[] = raw ? JSON.parse(raw) : [];
    if (!list.includes('chibi')) list.unshift('chibi');

    if (sig === null) {
      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
      _saveOwned(list);
      return list;
    }

    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
    if (sig !== _sign(list)) {
      _saveOwned(['chibi']);
      return ['chibi'];
    }

    return list;
  } catch {
    return ['chibi'];
  }
}

/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
export function setOwnedCharacters(list: string[]): void {
  if (!list.includes('chibi')) list.unshift('chibi');
  _saveOwned(list);
}

/** 캐릭터를 보유 목록에 추가 (뽑기 완료 후 호출) */
export function addOwnedCharacter(id: string): void {
  const owned = getOwnedCharacters();
  if (!owned.includes(id)) {
    owned.push(id);
    _saveOwned(owned);
  }
}

/** 선택된 캐릭터 ID 반환. 없으면 'chibi'. */
export function getSelectedCharacter(): string {
  return localStorage.getItem(SELECTED_KEY) ?? 'chibi';
}

/** 선택된 캐릭터 저장 */
export function setSelectedCharacter(id: string): void {
  localStorage.setItem(SELECTED_KEY, id);
}

/** 소유 목록과 교차 검증하여 안전한 캐릭터 ID 반환. 미보유면 'chibi'로 강제 초기화. */
export function getSafeSelectedCharacter(): string {
  const selected = getSelectedCharacter();
  const owned = getOwnedCharacters();
  if (owned.includes(selected)) return selected;
  // 변조 감지 → chibi로 강제 초기화
  setSelectedCharacter('chibi');
  return 'chibi';
}

/** 캐릭터 정의 조회 */
export function getCharacterDef(id: string): CharacterDef {
  return CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
}

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// ── 배경화면 풀 정의 ─────────────────────────────────────────────────────
// 등급 없음. 10종 균등 확률.
// 뽑기당 드롭율 3.5% → 종당 실효 확률 0.35% (캐릭터 UR과 동일 수준)
const WP_DROP_CHANCE = 0.035; // 슬롯당 3.5% → 종당 실효 확률 약 1.17%
const WP_POOL = [
  { id: 'wp_hanok'     },
  { id: 'wp_lake'      },
  { id: 'wp_maehwa'    },
  { id: 'wp_gold_mine' },
  { id: 'wp_fantasy'   },
];

function pullWallpaper(): { id: string } {
  return WP_POOL[Math.floor(Math.random() * WP_POOL.length)];
}

// ── 뽑기 풀 정의 ────────────────────────────────────────────────────────
// R 80% (10종 균등 배분), SR 19.3% (8종 균등 배분), UR 0.7% (2종 균등 배분)
const SR_W  = 19.3 / 8;   // ≈ 2.413%
const POOL = [
  // ── R등급 ──
  { id: 'log',     grade: 'R',  weight: 8 },
  { id: 'swap',    grade: 'R',  weight: 8 },
  { id: 'sum',     grade: 'R',  weight: 8 },
  { id: 'fork',    grade: 'R',  weight: 8 },
  { id: 'seed',    grade: 'R',  weight: 8 },
  { id: 'session', grade: 'R',  weight: 8 },
  { id: 'branch',  grade: 'R',  weight: 8 },
  { id: 'hook',    grade: 'R',  weight: 8 },
  { id: 'socket',  grade: 'R',  weight: 8 },
  { id: 'index',   grade: 'R',  weight: 8 },
  // ── SR등급 ──
  { id: 'hacker',   grade: 'SR', weight: SR_W },
  { id: 'miner',    grade: 'SR', weight: SR_W },
  { id: 'maehwa',   grade: 'SR', weight: SR_W },
  { id: 'archieve', grade: 'SR', weight: SR_W },
  { id: 'glitch',   grade: 'SR', weight: SR_W },
  { id: 'noise',    grade: 'SR', weight: SR_W },
  { id: 'knight',   grade: 'SR', weight: SR_W },
  { id: 'gumi',     grade: 'SR', weight: SR_W },
  // ── UR등급 ──
  { id: 'sentinel', grade: 'UR', weight: 0.35 },
  { id: 'legacy',   grade: 'UR', weight: 0.35 },
];

function pullOne(): { id: string; grade: string } {
  const total = POOL.reduce((s, c) => s + c.weight, 0);
  let r = Math.random() * total;
  for (const c of POOL) {
    r -= c.weight;
    if (r <= 0) return { id: c.id, grade: c.grade };
  }
  return { id: POOL[POOL.length - 1].id, grade: POOL[POOL.length - 1].grade };
}

// ── 요청 처리 ───────────────────────────────────────────────────────────
Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { pullType } = await req.json(); // 'single' | 'multi'

    if (pullType !== 'single' && pullType !== 'multi') {
      return new Response(
        JSON.stringify({ error: 'Invalid pullType' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const cost = pullType === 'multi' ? 900 : 100;
    const count = pullType === 'multi' ? 10 : 1;

    // 인증
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Missing authorization header' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    );

    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // ── 1. SKOR 잔액 + 보유 캐릭터 + 보유 배경화면 병렬 조회 ────────
    const [{ data: skorData }, { data: owned }, { data: ownedWp }] = await Promise.all([
      supabaseAdmin.from('user_skor').select('balance').eq('user_id', user.id).single(),
      supabaseAdmin.from('user_characters').select('character_id').eq('user_id', user.id),
      supabaseAdmin.from('user_wallpapers').select('wallpaper_id').eq('user_id', user.id),
    ]);

    const balance = skorData?.balance ?? 0;
    if (balance < cost) {
      return new Response(
        JSON.stringify({ error: 'Insufficient SKOR', balance }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // ── 2. 슬롯별 결정: 각 슬롯은 배경화면 또는 캐릭터 중 하나
    //       총합 = count, 추가 드롭 없음 ────────────────────────────────
    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));

    const characters: { id: string; grade: string; isNew: boolean }[] = [];
    const wallpapers: { id: string; isNew: boolean }[] = [];

    for (let i = 0; i < count; i++) {
      if (Math.random() < WP_DROP_CHANCE) {
        // 이 슬롯은 배경화면
        const wp = pullWallpaper();
        wallpapers.push({ id: wp.id, isNew: !ownedWpSet.has(wp.id) });
        ownedWpSet.add(wp.id); // 같은 pull 내 중복 isNew 방지
      } else {
        // 이 슬롯은 캐릭터
        const char = pullOne();
        characters.push({ id: char.id, grade: char.grade, isNew: !ownedSet.has(char.id) });
        ownedSet.add(char.id); // 같은 pull 내 중복 isNew 방지
      }
    }

    // ── 3. 신규 배경화면 등록 ────────────────────────────────────────────
    const newWps = wallpapers
      .filter(w => w.isNew)
      .map(w => ({ user_id: user.id, wallpaper_id: w.id }));

    // ── 4. 신규 캐릭터 등록 + 중복 카운트 증가 + SKOR 차감 병렬 처리 ─────
    // 같은 캐릭터가 10연차에서 중복 등장할 수 있으므로 횟수 집계 후 처리
    const newChars = [...new Map(
      characters
        .filter(c => c.isNew)
        .map(c => [c.id, { user_id: user.id, character_id: c.id }])
    ).values()];

    // 중복 캐릭터별 횟수 집계 (같은 캐릭터가 10연차에서 2번 나오면 +2)
    const dupCountMap = new Map<string, number>();
    characters.filter(c => !c.isNew).forEach(c => {
      dupCountMap.set(c.id, (dupCountMap.get(c.id) ?? 0) + 1);
    });

    const newBalance = balance - cost;
    const [charResult, , wpResult, skorResult] = await Promise.all([
      newChars.length > 0
        ? supabaseAdmin.from('user_characters').upsert(newChars, { onConflict: 'user_id,character_id' })
        : Promise.resolve({ error: null }),
      // 중복 카운트 증가: RPC로 atomic increment
      dupCountMap.size > 0
        ? Promise.all([...dupCountMap.entries()].map(([charId, inc]) =>
            supabaseAdmin.rpc('increment_duplicate_count', {
              p_user_id: user.id,
              p_character_id: charId,
              p_amount: inc,
            })
          ))
        : Promise.resolve(null),
      // 신규 배경화면 등록
      newWps.length > 0
        ? supabaseAdmin.from('user_wallpapers').upsert(newWps, { onConflict: 'user_id,wallpaper_id' })
        : Promise.resolve({ error: null }),
      supabaseAdmin.from('user_skor').upsert(
        { user_id: user.id, balance: newBalance, updated_at: new Date().toISOString() },
        { onConflict: 'user_id' }
      ),
    ]);

    if (charResult && 'error' in charResult && charResult.error) {
      console.error('user_characters upsert 실패:', charResult.error);
      return new Response(
        JSON.stringify({ error: 'Failed to save characters', detail: charResult.error }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (wpResult && 'error' in wpResult && wpResult.error) {
      console.error('user_wallpapers upsert 실패:', wpResult.error);
      return new Response(
        JSON.stringify({ error: 'Failed to save wallpapers', detail: wpResult.error }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (skorResult && 'error' in skorResult && skorResult.error) {
      console.error('user_skor upsert 실패:', skorResult.error);
    }

    // ── 6. 응답 ───────────────────────────────────────────────────────
    const hasUR = characters.some(c => c.grade === 'UR');

    return new Response(
      JSON.stringify({
        success: true,
        video: hasUR ? 'red' : 'green',
        characters,
        wallpapers,
        remainingSkor: Math.floor(newBalance),
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

