35	  constructor(scene: Phaser.Scene, x: number, y: number, speed: number = 300, texturePrefix: string = '') {
36	    // 기본 텍스처는 front (정면)
37	    super(scene, x, y, `${texturePrefix}front`);
38	    this.speed = speed;
39	    this.baseSpeed = speed; // 기본 속도 저장
40	    this.texturePrefix = texturePrefix;
41	
42	    // 씬에 추가
43	    scene.add.existing(this);
44	    scene.physics.add.existing(this);
45	
46	    // 캐릭터 크기 설정
47	    this.setDisplaySize(50, 80);
48	
49	    // 히트박스: 텍스처 해상도와 무관하게 world pixel 크기 고정
50	    // setSize/setOffset 은 frame pixel 단위이므로 scaleX/Y 로 역산
51	    // 목표 world 크기: 20×40 px (display 50×80 의 40%/50%), 중앙 정렬
52	    const sx = this.scaleX;  // = 50 / textureWidth
53	    const sy = this.scaleY;  // = 80 / textureHeight
54	    this.setSize(16 / sx, 40 / sy);
55	    this.setOffset((50 - 16) / 2 / sx, (80 - 40) / 2 / sy);
56	
57	    // 물리 설정
58	    this.setCollideWorldBounds(true);
59	    this.setImmovable(true);
60	
61	    // Phaser 키보드 입력
