      duration: 600,
      ease: 'Quad.easeOut',
      onComplete: () => {
        g.destroy();
        this.activeGraphics = this.activeGraphics.filter(item => item !== g);
      },
    });
  }

  private spawnPetals(cx: number, cy: number, scene: Phaser.Scene): void {
    const colors = [0xee82ee, 0xff99cc, 0xdda0dd, 0xcc66cc];
