import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import { GUMI_PARAMS } from '../config/abilityParams';

/**
 * 구미 (UR) — 이동속도 버프 / 점수마다 주변 똥 밀어내기 + 짧은 무적
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;
  private invincibleUntil = 0;

  private activeGraphics: Phaser.GameObjects.Graphics[] = [];

  override getPlayerSpeedBonus(): number {
    return GUMI_PARAMS.speedBonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.invincibleInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.activate(api);
    }
  }

  override onHitPoop(_api: GameSceneAPI): boolean {
    return Date.now() < this.invincibleUntil;
  }

  private activate(api: GameSceneAPI): void {
    const { scene, player } = api;

    this.invincibleUntil = Date.now() + GUMI_PARAMS.invincibleDuration;

    api.poops.getChildren().forEach(child => {
      const sp = child as Phaser.Physics.Arcade.Sprite;
      if (!sp.active) return;
      const dx = sp.x - player.x;
      const dy = sp.y - player.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const force = 500 * (1 - Math.min(dist / 300, 0.9));
      const body = sp.body as Phaser.Physics.Arcade.Body | null;
      if (body) {
        body.setVelocityX(body.velocity.x + (dx / dist) * force);
        body.setVelocityY(body.velocity.y + (dy / dist) * force * 0.5);
      }
    });

    scene.tweens.add({
      targets: player,
      alpha: 0.3,
      duration: 120,
      yoyo: true,
      repeat: Math.floor(GUMI_PARAMS.invincibleDuration / 240) - 1,
      onComplete: () => { player.setAlpha(1); },
    });

    this.drawShockwave(player.x, player.y, scene);
  }

  private drawShockwave(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics();
    g.lineStyle(3, 0xff88cc, 1);
    g.strokeCircle(x, y, 20);
    g.setDepth(200);
    this.activeGraphics.push(g);

    scene.tweens.add({
      targets: g,
      scaleX: 6,
      scaleY: 6,
      alpha: 0,
      duration: 400,
      ease: 'Quad.easeOut',
      onComplete: () => {
        g.destroy();
        this.activeGraphics = this.activeGraphics.filter(item => item !== g);
      },
    });
  }

  override onDestroy(api: GameSceneAPI): void {
    this.invincibleUntil = 0;
    api.scene.tweens.killTweensOf(api.player);
    api.player.setAlpha(1);
    this.activeGraphics.forEach(g => {
      api.scene.tweens.killTweensOf(g);
      if (g.active) g.destroy();
    });
    this.activeGraphics = [];
  }
}

