 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;

  override onCollectSpecial(type: SpecialPoopType): number {
    return (type === 'gold' || type === 'diamond') ? GUMI_PARAMS.collectBonus : 0;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.bloomInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.bloom(api);
    }
  }

  private bloom(api: GameSceneAPI): void {
    for (let i = 0; i < GUMI_PARAMS.bloomGoldCount; i++) {
      api.spawnGoldPoop();
    }
    api.spawnDiamondPoop();
    this.spawnBloomEffect(api.player.x, api.player.y, api.scene);
  }

  private spawnBloomEffect(cx: number, cy: number, scene: Phaser.Scene): void {
    const colors = [0xee82ee, 0xff99cc, 0xdda0dd, 0xcc66cc, 0xff66aa];
    const PETAL_COUNT = 14;

    for (let i = 0; i < PETAL_COUNT; i++) {
      const petal = scene.add.graphics().setDepth(121);
      const angle = (i / PETAL_COUNT) * Math.PI * 2;
      const r = Phaser.Math.Between(10, 50);
      const startX = cx + Math.cos(angle) * r * 0.3;
      const startY = cy + Math.sin(angle) * r * 0.3;
      petal.setPosition(startX, startY);
      petal.fillStyle(colors[i % colors.length], 0.9);
      petal.fillEllipse(0, 0, Phaser.Math.Between(4, 8), Phaser.Math.Between(8, 13));
      petal.setAngle(Phaser.Math.FloatBetween(0, 360));

