        targets: petal,
        x: cx + Math.cos(angle) * r * 3.5,
        y: cy + Math.sin(angle) * r * 3.5 + Phaser.Math.Between(10, 40),
        angle: petal.angle + Phaser.Math.FloatBetween(-180, 180),
        alpha: 0,
        duration: Phaser.Math.Between(500, 850),
        ease: 'Sine.easeOut',
        onComplete: () => petal.destroy(),
      });
