import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { GUMI_PARAMS } from '../config/abilityParams';

/**
 * 구미 (UR) — 구미호의 영기로 점수 배율 상승 / 여우불 강림으로 전체 소각
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;
  private accum = 0;

  private activeGraphics: Phaser.GameObjects.Graphics[] = [];

  override getTickScore(base: number): number {
    this.accum += base * GUMI_PARAMS.scoreExtra;
    const bonus = Math.floor(this.accum);
    this.accum -= bonus;
    return base + bonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.foxFire(api);
    }
  }

  private foxFire(api: GameSceneAPI): void {
    const { scene, player, poops } = api;

    poops.getChildren().forEach(child => {
      const sp = child as Phaser.Physics.Arcade.Sprite;
      if (!sp.active) return;
      this.spawnPetals(sp.x, sp.y, scene);
      (sp as unknown as PoolablePoopBase).recycle();
    });

    this.spawnFoxFireRing(player.x, player.y, scene);
  }

  private spawnFoxFireRing(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics();
    g.lineStyle(4, 0xff8800, 1);
    g.strokeCircle(x, y, 15);
    g.setDepth(200);
    this.activeGraphics.push(g);

    scene.tweens.add({
      targets: g,
      scaleX: 22,
      scaleY: 22,
      alpha: 0,
      duration: 600,
      ease: 'Quad.easeOut',
      onComplete: () => {
        g.destroy();
        this.activeGraphics = this.activeGraphics.filter(item => item !== g);
      },
    });
  }

  private spawnPetals(cx: number, cy: number, scene: Phaser.Scene): void {
    const colors = [0xee82ee, 0xff99cc, 0xdda0dd, 0xcc66cc];
    for (let i = 0; i < 6; i++) {
      const petal = scene.add.graphics().setDepth(121);
      const startX = cx + Phaser.Math.Between(-10, 10);
      const startY = cy + Phaser.Math.Between(-10, 10);
      petal.setPosition(startX, startY);
      petal.fillStyle(colors[Math.floor(Math.random() * colors.length)], 0.9);
      petal.fillEllipse(0, 0, Phaser.Math.Between(4, 7), Phaser.Math.Between(7, 11));
      petal.setAngle(Phaser.Math.Between(0, 360));

      scene.tweens.add({
        targets: petal,
        x: startX + Phaser.Math.Between(-30, 30),
        y: startY + Phaser.Math.Between(-20, 45),
        angle: petal.angle + Phaser.Math.Between(-150, 150),
        alpha: 0,
        duration: Phaser.Math.Between(400, 750),
        ease: 'Sine.easeIn',
        onComplete: () => petal.destroy(),
      });
    }
  }

  override onDestroy(api: GameSceneAPI): void {
    this.activeGraphics.forEach(g => {
      api.scene.tweens.killTweensOf(g);
      if (g.active) g.destroy();
    });
    this.activeGraphics = [];
  }
}

