      // 잠시 맺힌 후 외곽으로 퍼지며 사라짐
      scene.tweens.add({
        targets: g,
        x: player.x + Math.cos(angle) * ringR * 4,
        y: player.y + Math.sin(angle) * ringR * 4,
        scaleX: 0.15,
        scaleY: 0.15,
        alpha: 0,
        delay: i * 30,          // 하나씩 순서대로 터지는 느낌
        duration: 550,
        ease: 'Cubic.easeIn',
        onComplete: () => g.destroy(),
      });

      // 여우불 1개 = 금똥 1개
      scene.time.delayedCall(i * 30 + 100, () => api.spawnGoldPoop());
    }
  }

  private drawFoxFireOrb(g: Phaser.GameObjects.Graphics): void {
    // 외곽 글로우 (연파랑)
    g.fillStyle(0x88ccff, 0.25);
    g.fillCircle(0, 0, 13);
    // 중간 (청백)
    g.fillStyle(0xbbddff, 0.6);
    g.fillCircle(0, 0, 8);
    // 핵 (순백)
    g.fillStyle(0xffffff, 1);
    g.fillCircle(0, 0, 4);
  }
}

