import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { GUMI_PARAMS } from '../config/abilityParams';

const SPEED = 300;   // px/s
const FPS   = 60;
const SPF   = SPEED / FPS;  // px per frame
const HIT_R = 18;   // 충돌 판정 반경 (px)

interface FoxFire {
  g: Phaser.GameObjects.Graphics;
  vx: number;
  vy: number;
}

/**
 * 구미 (UR) — 구미호의 황금 친화력 / 여우불 9개로 닿은 똥을 금똥으로 변환
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;
  private foxFires: FoxFire[] = [];

  override onCollectSpecial(type: SpecialPoopType): number {
    return (type === 'gold' || type === 'diamond') ? GUMI_PARAMS.collectBonus : 0;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.summonFoxFires(api);
    }
  }

  private summonFoxFires(api: GameSceneAPI): void {
    const { scene, player } = api;
    const N = GUMI_PARAMS.foxFireCount;

    for (let i = 0; i < N; i++) {
      const ringAngle = (i / N) * Math.PI * 2;
      const startX = player.x + Math.cos(ringAngle) * 40;
      const startY = player.y + Math.sin(ringAngle) * 40;

      const g = scene.add.graphics().setDepth(200);
      this.drawFoxFireOrb(g);
      g.setPosition(startX, startY);

      const flyAngle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      this.foxFires.push({ g, vx: Math.cos(flyAngle) * SPF, vy: Math.sin(flyAngle) * SPF });
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    if (this.foxFires.length === 0) return;

    const W = 400;
    const H = 650;
    const activePoops = api.poops.getChildren().filter(
      p => (p as Phaser.Physics.Arcade.Sprite).active
    ) as Phaser.Physics.Arcade.Sprite[];

    const remaining: FoxFire[] = [];

    for (const fire of this.foxFires) {
      fire.g.x += fire.vx;
      fire.g.y += fire.vy;

      // 화면 밖으로 나가면 소멸
      if (fire.g.x < -30 || fire.g.x > W + 30 || fire.g.y < -30 || fire.g.y > H) {
        fire.g.destroy();
        continue;
      }

      let hit = false;
      for (const poop of activePoops) {
        const dx = fire.g.x - poop.x;
        const dy = fire.g.y - poop.y;
        if (dx * dx + dy * dy < HIT_R * HIT_R) {
          const px = poop.x;
          const py = poop.y;
          (poop as unknown as PoolablePoopBase).recycle();
          api.spawnGoldPoopAt(px, py);
          this.spawnHitFlash(px, py, api.scene);
          fire.g.destroy();
          hit = true;
          break;
        }
      }

      if (!hit) remaining.push(fire);
    }

    this.foxFires = remaining;
  }

  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics().setDepth(201);
    g.fillStyle(0xffd700, 0.9);
    g.fillCircle(x, y, 10);
    scene.tweens.add({
      targets: g,
      scaleX: 2.5,
      scaleY: 2.5,
      alpha: 0,
      duration: 280,
      ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    });
  }

  private drawFoxFireOrb(g: Phaser.GameObjects.Graphics): void {
    g.fillStyle(0x88ccff, 0.25);
    g.fillCircle(0, 0, 13);
    g.fillStyle(0xbbddff, 0.6);
    g.fillCircle(0, 0, 8);
    g.fillStyle(0xffffff, 1);
    g.fillCircle(0, 0, 4);
  }

  override onDestroy(api: GameSceneAPI): void {
    api.scene.tweens.killTweensOf(api.player);
    this.foxFires.forEach(f => f.g.destroy());
    this.foxFires = [];
  }
}

