import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';
import { GUMI_PARAMS } from '../config/abilityParams';

/**
 * 구미 (UR) — 구미호의 황금 친화력 / 9개 여우불로 금똥 소환
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;

  override onCollectSpecial(type: SpecialPoopType): number {
    return (type === 'gold' || type === 'diamond') ? GUMI_PARAMS.collectBonus : 0;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.summonFoxFires(api);
    }
  }

  private summonFoxFires(api: GameSceneAPI): void {
    const { scene, player } = api;
    const N = GUMI_PARAMS.foxFireCount;

    for (let i = 0; i < N; i++) {
      const angle = (i / N) * Math.PI * 2;
      const ringR = 45;
      const startX = player.x + Math.cos(angle) * ringR;
      const startY = player.y + Math.sin(angle) * ringR;

      const g = scene.add.graphics().setDepth(200);
      this.drawFoxFireOrb(g);
      g.setPosition(startX, startY);

      // 잠시 맺힌 후 외곽으로 퍼지며 사라짐
      scene.tweens.add({
        targets: g,
        x: player.x + Math.cos(angle) * ringR * 4,
        y: player.y + Math.sin(angle) * ringR * 4,
        scaleX: 0.15,
        scaleY: 0.15,
        alpha: 0,
        delay: i * 30,          // 하나씩 순서대로 터지는 느낌
        duration: 550,
        ease: 'Cubic.easeIn',
        onComplete: () => g.destroy(),
      });

      // 여우불 1개 = 금똥 1개
      scene.time.delayedCall(i * 30 + 100, () => api.spawnGoldPoop());
    }
  }

  private drawFoxFireOrb(g: Phaser.GameObjects.Graphics): void {
    // 외곽 글로우 (연파랑)
    g.fillStyle(0x88ccff, 0.25);
    g.fillCircle(0, 0, 13);
    // 중간 (청백)
    g.fillStyle(0xbbddff, 0.6);
    g.fillCircle(0, 0, 8);
    // 핵 (순백)
    g.fillStyle(0xffffff, 1);
    g.fillCircle(0, 0, 4);
  }
}

