          (poop as unknown as PoolablePoopBase).recycle();
          api.spawnGoldPoopAt(px, py);
          this.spawnHitFlash(px, py, api.scene);
          fire.g.destroy();
          hit = true;
          break;
        }
      }

      if (!hit) remaining.push(fire);
    }

    this.foxFires = remaining;
  }

  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
    const g = scene.add.graphics().setDepth(201);
    g.fillStyle(0xffd700, 0.9);
    g.fillCircle(x, y, 10);
    scene.tweens.add({
      targets: g,
      scaleX: 2.5,
      scaleY: 2.5,
      alpha: 0,
      duration: 280,
      ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    });
  }

  private drawFoxFireOrb(g: Phaser.GameObjects.Graphics): void {
    g.fillStyle(0x88ccff, 0.25);
    g.fillCircle(0, 0, 13);
    g.fillStyle(0xbbddff, 0.6);
    g.fillCircle(0, 0, 8);
    g.fillStyle(0xffffff, 1);
    g.fillCircle(0, 0, 4);
  }

  override onDestroy(api: GameSceneAPI): void {
    api.scene.tweens.killTweensOf(api.player);
    this.foxFires.forEach(f => f.g.destroy());
    this.foxFires = [];
  }
}

