  0xffffff,  // 흰
  0x444444,  // 검
];

interface FoxFire {
  g: Phaser.GameObjects.Graphics;
  baseVx: number;
  speedY: number;  // 개체마다 상승 속도 다르게
  phase: number;
  freq: number;
  frame: number;
}

/**
 * 구미 (UR) — 구미호의 황금 친화력 / 여우불 9개로 닿은 똥을 금똥으로 변환
