        fontStyle: 'bold',
        stroke: '#000000',
        strokeThickness: 4
      }).setOrigin(0.5).setDepth(200);

      // 로컬 최고 점수
      this.add.text(cx, H / 2 + 20, `개인 최고: ${this.highScore}`, {
        fontSize: '24px',
        color: '#FFD700',
